<?php
namespace App\Http\Controllers;use App\Http\Requests\UpdatePortfolioRequest;use App\Models\{MediaAsset,Portfolio,PortfolioImage};use App\Services\Branding\{BusinessBrandingPresenter,FlipbookBrandingPresenter};use App\Services\Media\MediaDeliveryService;use App\Services\Portfolio\PortfolioManager;use App\Services\Team\TeamAuthorization;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Inertia\Inertia;
class PortfolioController extends Controller{private function context():array{$actor=Auth::user();$owner=app(TeamAuthorization::class)->ownerFor($actor)??$actor;abort_unless(app(TeamAuthorization::class)->allows($actor,$owner,'manage_portfolio'),403);return[$actor,$owner];}public function edit(PortfolioManager$m){[$actor,$owner]=$this->context();$p=$m->get($owner);$assets=MediaAsset::with('variants')->where('owner_id',$owner->id)->where('kind','photo')->where('state','completed')->latest()->limit(500)->get();return Inertia::render('Settings/Portfolio',['section'=>'portfolio','settings'=>$this->settings($p,$actor->id===$owner->id),'availableImages'=>$assets->map(fn($a)=>['id'=>$a->id,'name'=>$a->original_filename,'thumbnail_url'=>route('settings.portfolio.asset',$a)]),'currencies'=>config('portfolio.currencies'),'imageLimit'=>(int)config('portfolio.image_limit',100),'canManagePayments'=>$actor->id===$owner->id]);}public function update(UpdatePortfolioRequest$r,PortfolioManager$m){[$actor,$owner]=$this->context();$p=$m->get($owner);$m->save($p,$r->validated(),$r->file('cover'),$actor->id===$owner->id);return back()->with('success','Portfolio settings saved.');}public function preview(PortfolioManager$m){[$actor,$owner]=$this->context();return $this->render($m->get($owner),true);}public function public(Portfolio$p){abort_unless($p->status==='published',404);return $this->render($p,false);}private function render(Portfolio$p,bool$preview){$p->load(['owner.flipbookSetting','owner.businessBranding','images.mediaAsset.variants','services']);$branding=app(FlipbookBrandingPresenter::class)->portfolio($p->owner);$contacts=app(BusinessBrandingPresenter::class)->portfolio($p->owner);$images=$p->images->filter(fn($i)=>$i->mediaAsset&&!$i->mediaAsset->trashed())->map(fn($i)=>['url'=>$preview?route('settings.portfolio.image',$i):route('portfolio.image',[$p,$i]),'alt'=>$i->mediaAsset->original_filename]);$services=$p->services->whereNull('archived_at')->where('enabled',true)->values()->map(fn($s)=>['name'=>$s->name,'price'=>$s->price]);$payment=$p->show_payment_details?collect(['upi_id'=>$p->upi_id,'upi_phone'=>$p->upi_phone,'bank_name'=>$p->bank_name,'account_holder_name'=>$p->account_holder_name,'account_number'=>$p->account_number,'account_type'=>$p->account_type,'ifsc'=>$p->ifsc])->filter()->all():[];return response()->view('portfolio.show',compact('p','branding','contacts','images','services','payment','preview'));}public function cover(Portfolio$p=null){if($p){abort_unless($p->status==='published',404);}else{[, $owner]=$this->context();$p=$owner->portfolio;}abort_unless($p?->cover_object_key,404);return $this->stream($p->cover_disk,$p->cover_object_key,$p->cover_mime_type,$p->cover_size_bytes);}public function asset(MediaAsset$a,MediaDeliveryService$d){[, $owner]=$this->context();abort_unless($a->owner_id===$owner->id,403);return$d->deliver($a->variant('thumbnail')?:$a->variant('optimized')?:abort(404));}public function image(PortfolioImage$i,MediaDeliveryService$d){if(request()->routeIs('portfolio.image')){$p=request()->route('portfolio');abort_unless($p instanceof Portfolio&&$p->status==='published'&&$i->portfolio_id===$p->id,404);}else{[, $owner]=$this->context();abort_unless($i->portfolio?->studio_owner_id===$owner->id,403);}return$d->deliver($i->mediaAsset?->variant('optimized')?:abort(404));}private function stream($disk,$key,$mime,$size){$s=\Storage::disk($disk)->readStream($key);abort_unless(is_resource($s),404);return response()->stream(function()use($s){fpassthru($s);fclose($s);},200,['Content-Type'=>$mime,'Content-Length'=>$size,'Cache-Control'=>'private, no-store']);}private function settings(Portfolio$p,bool$pay):array{return['name'=>$p->name,'website_url'=>$p->website_url,'about_us'=>$p->about_us,'currency_code'=>$p->currency_code,'status'=>$p->status,'show_payment_details'=>$pay&&$p->show_payment_details,'cover_url'=>$p->cover_object_key?route('settings.portfolio.cover'):null,'image_ids'=>$p->images->pluck('media_asset_id'),'services'=>$p->services->whereNull('archived_at')->values()->map->only(['id','name','price','enabled','is_custom']),'upi_id'=>$pay?$p->upi_id:null,'upi_phone'=>$pay?$p->upi_phone:null,'bank_name'=>$pay?$p->bank_name:null,'account_holder_name'=>$pay?$p->account_holder_name:null,'account_number'=>'','account_number_masked'=>$pay&&$p->account_number?'••••'.substr($p->account_number,-4):null,'account_type'=>$pay?$p->account_type:null,'ifsc'=>$pay?$p->ifsc:null,'public_url'=>route('portfolio.show',$p)];}}
